-- Shared Auth schema: clients, users, profiles, external identities,
-- login attempts, authorization codes, sessions, roles, and user roles.
-- Schema only: roles, assignments, and clients are created explicitly.
--
-- All primary keys are UUIDv7 values generated by the application; no
-- database-side default is used.

-- Each row is one OAuth app registration at one provider (Google/GitHub) for
-- one website, identified by the provider-issued client_id. A website using
-- both providers has two rows. client_secret_enc is the provider's OAuth app
-- secret (encrypted); auth_secret_hash authenticates the website's own
-- backend calling this service, separate from the provider secret.
CREATE TABLE clients (
    id                 UUID PRIMARY KEY,
    provider           VARCHAR(32) NOT NULL,
    client_id          VARCHAR(255) NOT NULL,
    client_secret_enc  TEXT NOT NULL,
    auth_secret_hash   VARCHAR(255) NOT NULL,
    name               VARCHAR(255) NOT NULL,
    redirect_url       TEXT NOT NULL,
    redirect_uris      TEXT[] NOT NULL,
    enabled            BOOLEAN NOT NULL DEFAULT true,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (provider, client_id)
);

CREATE TABLE users (
    id              UUID PRIMARY KEY,
    canonical_email VARCHAR(255) UNIQUE
);

CREATE TABLE roles (
    id         UUID PRIMARY KEY,
    key        VARCHAR(64) NOT NULL UNIQUE,
    name       VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE user_roles (
    user_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role_id    UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role_id)
);

CREATE INDEX user_roles_role_id_idx ON user_roles (role_id);

CREATE TABLE profiles (
    user_id               UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    display_name          VARCHAR(255),
    avatar_url            TEXT,
    display_name_managed  BOOLEAN NOT NULL DEFAULT false,
    avatar_url_managed    BOOLEAN NOT NULL DEFAULT false,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE external_identities (
    id               UUID PRIMARY KEY,
    user_id          UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    provider         VARCHAR(32) NOT NULL,
    provider_subject VARCHAR(255) NOT NULL,
    email            VARCHAR(255),
    email_verified   BOOLEAN NOT NULL DEFAULT false,
    display_name     VARCHAR(255),
    avatar_url       TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (provider, provider_subject)
);

CREATE INDEX external_identities_user_id_idx ON external_identities (user_id);

CREATE TABLE login_attempts (
    id                    UUID PRIMARY KEY,
    client_ref            UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
    provider              VARCHAR(32) NOT NULL,
    state                 VARCHAR(255) NOT NULL UNIQUE,
    nonce                 VARCHAR(255) NOT NULL,
    code_challenge        VARCHAR(255) NOT NULL,
    code_challenge_method VARCHAR(32) NOT NULL DEFAULT 'S256',
    redirect_uri          TEXT NOT NULL,
    product_state         TEXT NOT NULL,
    expires_at            TIMESTAMPTZ NOT NULL,
    consumed_at           TIMESTAMPTZ,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE auth_codes (
    id                    UUID PRIMARY KEY,
    code                  VARCHAR(255) NOT NULL UNIQUE,
    client_ref            UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
    user_id               UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    identity_id           UUID NOT NULL REFERENCES external_identities(id) ON DELETE CASCADE,
    redirect_uri          TEXT NOT NULL,
    code_challenge        VARCHAR(255) NOT NULL,
    code_challenge_method VARCHAR(32) NOT NULL DEFAULT 'S256',
    expires_at            TIMESTAMPTZ NOT NULL,
    consumed_at           TIMESTAMPTZ,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX auth_codes_user_id_idx ON auth_codes (user_id);
CREATE INDEX auth_codes_identity_id_idx ON auth_codes (identity_id);

CREATE TABLE sessions (
    id          UUID PRIMARY KEY,
    user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    identity_id UUID NOT NULL REFERENCES external_identities(id) ON DELETE CASCADE,
    client_ref  UUID NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
    expires_at  TIMESTAMPTZ NOT NULL,
    revoked_at  TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX sessions_user_id_idx ON sessions (user_id);
CREATE INDEX sessions_identity_id_idx ON sessions (identity_id);
